css:
.wiwa-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #f4efe1 0%, #e8ddc4 50%, #d4c29a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2a1f12;
    max-width: 1400px;
    margin: 0 auto;
}
.wiwa-sim-header {
    background: linear-gradient(135deg, #3d2817 0%, #5c3a1f 50%, #7a4a25 100%);
    color: #f4efe1;
    border-radius: 18px;
    padding: 36px 40px;
    text-align: center;
    margin-bottom: 24px;
    box-shadow: 0 16px 40px rgba(61, 40, 23, 0.28);
    border: 2px solid #8b6f3a;
    position: relative;
    overflow: hidden;
}
.wiwa-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, #c9a14a, #e8c36b, #c9a14a);
}
.wiwa-sim-header::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #2d5a3e, #4a7c5a, #2d5a3e);
}
.wiwa-sim-header-badge {
    display: inline-block;
    background: rgba(244, 239, 225, 0.15);
    color: #e8c36b;
    padding: 6px 16px;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 14px;
    border: 1px solid rgba(232, 195, 107, 0.4);
}
.wiwa-sim-header h1 {
    font-size: 2.2rem;
    font-weight: 700;
    margin: 0 0 10px 0;
    letter-spacing: -0.02em;
}
.wiwa-sim-subtitle {
    color: #d4b878;
    font-size: 1rem;
    font-style: italic;
    opacity: 0.9;
}
.wiwa-sim-period-bar {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 26px;
    margin-bottom: 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 4px 16px rgba(61, 40, 23, 0.1);
    border-left: 6px solid #2d5a3e;
}
.wiwa-sim-period-label {
    font-size: 0.95rem;
    font-weight: 600;
    color: #3d2817;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.wiwa-sim-period-label span:nth-child(2) {
    color: #2d5a3e;
    font-size: 1.3rem;
    margin: 0 4px;
}
.wiwa-sim-period-name {
    color: #7a4a25;
    font-weight: 600;
    font-size: 1.05rem;
    font-style: italic;
}
.wiwa-sim-briefing {
    background: #fffbf3;
    border: 1px solid #d4c29a;
    border-left: 6px solid #c9a14a;
    border-radius: 12px;
    padding: 24px 28px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(61, 40, 23, 0.06);
}
.wiwa-sim-briefing h3 {
    color: #3d2817;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.wiwa-sim-briefing #briefingText {
    color: #4a3624;
    line-height: 1.65;
    font-size: 0.95rem;
}
.wiwa-sim-briefing #briefingText strong {
    color: #7a4a25;
    font-weight: 700;
}
.wiwa-sim-status-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.wiwa-sim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 4px 14px rgba(61, 40, 23, 0.08);
    border-top: 4px solid #c9a14a;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.wiwa-sim-status-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(61, 40, 23, 0.14);
}
.wiwa-sim-status-card.wiwa-sim-cash { border-top-color: #2d5a3e; }
.wiwa-sim-status-card.wiwa-sim-cultural { border-top-color: #7a4a25; }
.wiwa-sim-status-card.wiwa-sim-governance { border-top-color: #c9a14a; }
.wiwa-sim-status-card.wiwa-sim-env { border-top-color: #4a7c5a; }
.wiwa-sim-status-card.wiwa-sim-reputation { border-top-color: #8b3a3a; }
.wiwa-sim-status-card.wiwa-sim-community { border-top-color: #5c3a1f; }
.wiwa-sim-label {
    color: #6b5842;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    margin-bottom: 8px;
}
.wiwa-sim-value {
    font-size: 1.65rem;
    font-weight: 700;
    color: #3d2817;
    letter-spacing: -0.01em;
}
.wiwa-sim-bar {
    height: 6px;
    background: #efe7d4;
    border-radius: 3px;
    margin-top: 10px;
    overflow: hidden;
}
.wiwa-sim-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, #c9a14a, #2d5a3e);
    border-radius: 3px;
    transition: width 0.4s ease;
    width: 0%;
}
.wiwa-sim-controls {
    background: #ffffff;
    border-radius: 16px;
    padding: 28px 32px;
    margin-bottom: 24px;
    box-shadow: 0 6px 20px rgba(61, 40, 23, 0.08);
    border: 1px solid #d4c29a;
}
.wiwa-sim-controls h3 {
    color: #3d2817;
    font-size: 1.15rem;
    font-weight: 700;
    margin: 0 0 22px 0;
    padding-bottom: 12px;
    border-bottom: 2px solid #c9a14a;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.wiwa-sim-decision-group {
    margin-bottom: 20px;
}
.wiwa-sim-decision-group label {
    display: block;
    color: #3d2817;
    font-size: 0.92rem;
    font-weight: 600;
    margin-bottom: 8px;
}
.wiwa-sim-select {
    background: #fffbf3;
    border: 1.5px solid #c9a14a;
    color: #3d2817;
    border-radius: 8px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
    font-family: inherit;
    cursor: pointer;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.wiwa-sim-select:focus {
    outline: none;
    border-color: #2d5a3e;
    box-shadow: 0 0 0 3px rgba(45, 90, 62, 0.15);
}
.wiwa-sim-select option {
    background: #ffffff;
    color: #3d2817;
    padding: 8px;
}
.wiwa-sim-help {
    color: #6b5842;
    font-size: 0.82rem;
    margin-top: 6px;
    font-style: italic;
    line-height: 1.4;
}
.wiwa-sim-button-row {
    display: flex;
    gap: 14px;
    margin-top: 28px;
    padding-top: 20px;
    border-top: 1px solid #e8ddc4;
}
.wiwa-sim-submit {
    background: linear-gradient(135deg, #2d5a3e, #4a7c5a) !important;
    border: none !important;
    color: #ffffff !important;
    padding: 12px 28px !important;
    border-radius: 10px !important;
    font-weight: 700 !important;
    font-size: 1rem !important;
    letter-spacing: 0.04em !important;
    box-shadow: 0 4px 12px rgba(45, 90, 62, 0.3) !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease !important;
    flex: 1;
}
.wiwa-sim-submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 18px rgba(45, 90, 62, 0.4) !important;
}
.wiwa-sim-undo {
    background: #fffbf3 !important;
    border: 1.5px solid #c9a14a !important;
    color: #7a4a25 !important;
    padding: 10px 20px !important;
    border-radius: 10px !important;
    font-weight: 600 !important;
}
.wiwa-sim-hint {
    background: linear-gradient(135deg, #fffbf3, #f4efe1);
    border: 1px solid #c9a14a;
    border-left: 5px solid #7a4a25;
    border-radius: 12px;
    padding: 18px 22px;
    margin-bottom: 24px;
    display: flex;
    align-items: center;
    gap: 18px;
    box-shadow: 0 4px 12px rgba(61, 40, 23, 0.08);
}
.wiwa-sim-hint-icon {
    font-size: 1.8rem;
    flex-shrink: 0;
}
.wiwa-sim-hint-text {
    color: #3d2817;
    font-size: 0.95rem;
    line-height: 1.55;
    font-style: italic;
}
.wiwa-sim-chart-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
}
.wiwa-sim-chart-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 4px 16px rgba(61, 40, 23, 0.08);
    border: 1px solid #e8ddc4;
    height: 320px;
    display: flex;
    flex-direction: column;
}
.wiwa-sim-chart-card h4 {
    color: #3d2817;
    font-size: 0.95rem;
    font-weight: 700;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.wiwa-sim-chart-card canvas {
    flex: 1;
    min-height: 0;
}
.wiwa-sim-history {
    background: #ffffff;
    border-radius: 14px;
    padding: 24px 28px;
    box-shadow: 0 4px 16px rgba(61, 40, 23, 0.08);
    border: 1px solid #e8ddc4;
}
.wiwa-sim-history h4 {
    color: #3d2817;
    font-size: 1rem;
    font-weight: 700;
    margin: 0 0 16px 0;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding-bottom: 10px;
    border-bottom: 2px solid #c9a14a;
}
.wiwa-sim-history table {
    color: #3d2817;
    font-size: 0.9rem;
}
.wiwa-sim-history table th {
    background: #f4efe1;
    color: #5c3a1f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.06em;
    border-bottom: 2px solid #c9a14a;
    padding: 10px 12px;
}
.wiwa-sim-history table td {
    padding: 10px 12px;
    border-bottom: 1px solid #e8ddc4;
}
@media (max-width: 768px) {
    .wiwa-sim-container { padding: 16px; }
    .wiwa-sim-header { padding: 24px 20px; }
    .wiwa-sim-header h1 { font-size: 1.5rem; }
    .wiwa-sim-status-grid { grid-template-columns: repeat(2, 1fr); }
    .wiwa-sim-chart-grid { grid-template-columns: 1fr; }
    .wiwa-sim-period-bar { flex-direction: column; gap: 10px; text-align: center; }
    .wiwa-sim-button-row { flex-direction: column; }
}

js:
(function() {
    'use strict';

    class WiwaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Empresa Comunitaria Wiwa Sey';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    key: 'round1',
                    nameKey: 'round1_name',
                    briefKey: 'round1_brief',
                    decisions: [
                        { id: 'decision1', labelKey: 'r1_d1_label', helpKey: 'r1_d1_help', options: [
                            { value: 'safety',       labelKey: 'r1_d1_opt_safety' },
                            { value: 'legal',        labelKey: 'r1_d1_opt_legal' },
                            { value: 'platform',     labelKey: 'r1_d1_opt_platform' },
                            { value: 'generational', labelKey: 'r1_d1_opt_gen' },
                            { value: 'selina',       labelKey: 'r1_d1_opt_selina' },
                            { value: 'regen',        labelKey: 'r1_d1_opt_regen' }
                        ]},
                        { id: 'decision2', labelKey: 'r1_d2_label', helpKey: 'r1_d2_help', options: [
                            { value: 'reject',   labelKey: 'r1_d2_opt_reject' },
                            { value: 'negotiate',labelKey: 'r1_d2_opt_negotiate' },
                            { value: 'accept',   labelKey: 'r1_d2_opt_accept' }
                        ]},
                        { id: 'decision3', labelKey: 'r1_d3_label', helpKey: 'r1_d3_help', options: [
                            { value: 'suspend',  labelKey: 'r1_d3_opt_suspend' },
                            { value: 'reduce',   labelKey: 'r1_d3_opt_reduce' },
                            { value: 'continue', labelKey: 'r1_d3_opt_continue' }
                        ]},
                        { id: 'decision4', labelKey: 'r1_d4_label', helpKey: 'r1_d4_help', options: [
                            { value: 'cabildo',  labelKey: 'r1_d4_opt_cabildo' },
                            { value: 'asesora',  labelKey: 'r1_d4_opt_asesora' },
                            { value: 'tesorero', labelKey: 'r1_d4_opt_tesorero' },
                            { value: 'coord',    labelKey: 'r1_d4_opt_coord' }
                        ]}
                    ]
                },
                {
                    key: 'round2',
                    nameKey: 'round2_name',
                    briefKey: 'round2_brief',
                    decisions: [
                        { id: 'decision1', labelKey: 'r2_d1_label', helpKey: 'r2_d1_help', options: [
                            { value: 'silence',       labelKey: 'r2_d1_opt_silence' },
                            { value: 'statement',     labelKey: 'r2_d1_opt_statement' },
                            { value: 'legal',         labelKey: 'r2_d1_opt_legal' },
                            { value: 'both',          labelKey: 'r2_d1_opt_both' }
                        ]},
                        { id: 'decision2', labelKey: 'r2_d2_label', helpKey: 'r2_d2_help', options: [
                            { value: 'none',     labelKey: 'r2_d2_opt_none' },
                            { value: 'basic',    labelKey: 'r2_d2_opt_basic' },
                            { value: 'complete', labelKey: 'r2_d2_opt_complete' }
                        ]},
                        { id: 'decision3', labelKey: 'r2_d3_label', helpKey: 'r2_d3_help', options: [
                            { value: 'pure',     labelKey: 'r2_d3_opt_pure' },
                            { value: 'balanced', labelKey: 'r2_d3_opt_balanced' },
                            { value: 'modern',   labelKey: 'r2_d3_opt_modern' }
                        ]},
                        { id: 'decision4', labelKey: 'r2_d4_label', helpKey: 'r2_d4_help', options: [
                            { value: 'accept_asis', labelKey: 'r2_d4_opt_accept' },
                            { value: 'renegotiate', labelKey: 'r2_d4_opt_negotiate' },
                            { value: 'reject',      labelKey: 'r2_d4_opt_reject' }
                        ]}
                    ]
                },
                {
                    key: 'round3',
                    nameKey: 'round3_name',
                    briefKey: 'round3_brief',
                    decisions: [
                        { id: 'decision1', labelKey: 'r3_d1_label', helpKey: 'r3_d1_help', options: [
                            { value: 'silence',    labelKey: 'r3_d1_opt_silence' },
                            { value: 'reactive',   labelKey: 'r3_d1_opt_reactive' },
                            { value: 'proactive',  labelKey: 'r3_d1_opt_proactive' },
                            { value: 'offensive',  labelKey: 'r3_d1_opt_offensive' }
                        ]},
                        { id: 'decision2', labelKey: 'r3_d2_label', helpKey: 'r3_d2_help', options: [
                            { value: 'minimal',  labelKey: 'r3_d2_opt_minimal' },
                            { value: 'moderate', labelKey: 'r3_d2_opt_moderate' },
                            { value: 'complete', labelKey: 'r3_d2_opt_complete' }
                        ]},
                        { id: 'decision3', labelKey: 'r3_d3_label', helpKey: 'r3_d3_help', options: [
                            { value: 'bank',     labelKey: 'r3_d3_opt_bank' },
                            { value: 'coop',     labelKey: 'r3_d3_opt_coop' },
                            { value: 'redd',     labelKey: 'r3_d3_opt_redd' },
                            { value: 'members',  labelKey: 'r3_d3_opt_members' }
                        ]},
                        { id: 'decision4', labelKey: 'r3_d4_label', helpKey: 'r3_d4_help', options: [
                            { value: 'formal',      labelKey: 'r3_d4_opt_formal' },
                            { value: 'hybrid',      labelKey: 'r3_d4_opt_hybrid' },
                            { value: 'consultive',  labelKey: 'r3_d4_opt_consultive' }
                        ]}
                    ]
                },
                {
                    key: 'round4',
                    nameKey: 'round4_name',
                    briefKey: 'round4_brief',
                    decisions: [
                        { id: 'decision1', labelKey: 'r4_d1_label', helpKey: 'r4_d1_help', options: [
                            { value: 'reject',       labelKey: 'r4_d1_opt_reject' },
                            { value: 'conditional',  labelKey: 'r4_d1_opt_conditional' },
                            { value: 'accept',       labelKey: 'r4_d1_opt_accept' }
                        ]},
                        { id: 'decision2', labelKey: 'r4_d2_label', helpKey: 'r4_d2_help', options: [
                            { value: 'traditional', labelKey: 'r4_d2_opt_traditional' },
                            { value: 'dual',        labelKey: 'r4_d2_opt_dual' },
                            { value: 'integrated',  labelKey: 'r4_d2_opt_integrated' }
                        ]},
                        { id: 'decision3', labelKey: 'r4_d3_label', helpKey: 'r4_d3_help', options: [
                            { value: 'tourism_only', labelKey: 'r4_d3_opt_tourism' },
                            { value: 'redd_tourism', labelKey: 'r4_d3_opt_redd' },
                            { value: 'full',         labelKey: 'r4_d3_opt_full' }
                        ]},
                        { id: 'decision4', labelKey: 'r4_d4_label', helpKey: 'r4_d4_help', options: [
                            { value: 'basic',       labelKey: 'r4_d4_opt_basic' },
                            { value: 'moderate',    labelKey: 'r4_d4_opt_moderate' },
                            { value: 'aggressive',  labelKey: 'r4_d4_opt_aggressive' }
                        ]}
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 124820000,
                    cultural: 72,
                    governance: 58,
                    env: 45,
                    reputation: 55,
                    community: 62,
                    cashHistory: [],
                    culturalHistory: [],
                    governanceHistory: [],
                    envHistory: [],
                    reputationHistory: [],
                    communityHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decision1: '',
                    decision2: '',
                    decision3: '',
                    decision4: ''
                };
            }
            var self = this;
            self._updateBriefing(state);
        }

        _updateBriefing(state) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var roundNameEl = document.getElementById('roundName');
            if (roundNameEl) roundNameEl.textContent = t(round.nameKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefKey);

            for (var i = 0; i < 4; i++) {
                var decConfig = round.decisions[i];
                var labelEl = document.getElementById('label' + (i + 1));
                var selectEl = document.getElementById('decision' + (i + 1));
                var helpEl = document.getElementById('help' + (i + 1));
                var groupEl = document.getElementById('decisionGroup' + (i + 1));

                if (decConfig) {
                    if (groupEl) groupEl.style.display = 'block';
                    if (labelEl) labelEl.textContent = t(decConfig.labelKey);
                    if (helpEl) helpEl.textContent = t(decConfig.helpKey);
                    if (selectEl) {
                        selectEl.innerHTML = '';
                        for (var j = 0; j < decConfig.options.length; j++) {
                            var opt = document.createElement('option');
                            opt.value = decConfig.options[j].value;
                            opt.textContent = t(decConfig.options[j].labelKey);
                            selectEl.appendChild(opt);
                        }
                        if (decConfig.options.length > 0) {
                            selectEl.value = decConfig.options[0].value;
                        }
                    }
                } else if (groupEl) {
                    groupEl.style.display = 'none';
                }
            }
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            /* v1.1.0: removed validate-time DOM write (validation is now side-effect free; panel refreshes on period:submitted). */
var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            for (var i = 0; i < round.decisions.length; i++) {
                var decId = round.decisions[i].id;
                var el = document.getElementById(decId);
                if (el) {
                    decisions[decId] = el.value;
                } else {
                    decisions[decId] = round.decisions[i].options[0].value;
                }
            }

            for (var k = 0; k < round.decisions.length; k++) {
                var did = round.decisions[k].id;
                if (!decisions[did]) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('decision_warning'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var cashDelta = 0;
            var culturalDelta = 0;
            var governanceDelta = 0;
            var envDelta = 0;
            var reputationDelta = 0;
            var communityDelta = 0;
            var narrativeParts = [];

            if (period === 1) {
                if (d.decision1 === 'safety') {
                    reputationDelta += 6; governanceDelta += 4; cashDelta -= 12000000;
                    narrativeParts.push(window.mySimulation.t('narr_r1_priority_safety'));
                } else if (d.decision1 === 'legal') {
                    envDelta += 8; governanceDelta += 3; cashDelta -= 8000000;
                    narrativeParts.push(window.mySimulation.t('narr_r1_priority_legal'));
                } else if (d.decision1 === 'platform') {
                    cashDelta += 4000000; governanceDelta += 2;
                    narrativeParts.push(window.mySimulation.t('narr_r1_priority_platform'));
                } else if (d.decision1 === 'generational') {
                    governanceDelta += 6; communityDelta += 5; culturalDelta -= 3;
                    narrativeParts.push(window.mySimulation.t('narr_r1_priority_gen'));
                } else if (d.decision1 === 'selina') {
                    reputationDelta -= 4; culturalDelta -= 5;
                    narrativeParts.push(window.mySimulation.t('narr_r1_priority_selina'));
                } else if (d.decision1 === 'regen') {
                    envDelta += 5; reputationDelta += 4; culturalDelta += 3;
                    narrativeParts.push(window.mySimulation.t('narr_r1_priority_regen'));
                }

                if (d.decision2 === 'reject') {
                    culturalDelta += 8; communityDelta += 4; governanceDelta += 5;
                    narrativeParts.push(window.mySimulation.t('narr_r1_selina_reject'));
                } else if (d.decision2 === 'negotiate') {
                    culturalDelta += 2; communityDelta -= 2; governanceDelta -= 1;
                    narrativeParts.push(window.mySimulation.t('narr_r1_selina_negotiate'));
                } else if (d.decision2 === 'accept') {
                    cashDelta += 4800000000 * 0.05; culturalDelta -= 15; governanceDelta -= 12; communityDelta -= 10;
                    narrativeParts.push(window.mySimulation.t('narr_r1_selina_accept'));
                }

                if (d.decision3 === 'suspend') {
                    envDelta += 10; cashDelta -= 18000000; reputationDelta += 3;
                    narrativeParts.push(window.mySimulation.t('narr_r1_trails_suspend'));
                } else if (d.decision3 === 'reduce') {
                    envDelta += 4; cashDelta -= 9000000;
                    narrativeParts.push(window.mySimulation.t('narr_r1_trails_reduce'));
                } else if (d.decision3 === 'continue') {
                    envDelta -= 12; reputationDelta -= 5;
                    narrativeParts.push(window.mySimulation.t('narr_r1_trails_continue'));
                }

                if (d.decision4 === 'cabildo') {
                    culturalDelta += 4; governanceDelta += 3;
                } else if (d.decision4 === 'asesora') {
                    governanceDelta -= 2; culturalDelta -= 2; reputationDelta += 2;
                } else if (d.decision4 === 'tesorero') {
                    governanceDelta += 2; cashDelta += 2000000;
                } else if (d.decision4 === 'coord') {
                    reputationDelta += 3; governanceDelta += 2;
                }
            }

            if (period === 2) {
                if (d.decision1 === 'silence') {
                    reputationDelta -= 8; culturalDelta -= 4;
                    narrativeParts.push(window.mySimulation.t('narr_r2_selina_silence'));
                } else if (d.decision1 === 'statement') {
                    reputationDelta += 5; culturalDelta += 4;
                    narrativeParts.push(window.mySimulation.t('narr_r2_selina_statement'));
                } else if (d.decision1 === 'legal') {
                    cashDelta -= 15000000; culturalDelta += 3; reputationDelta += 2;
                    narrativeParts.push(window.mySimulation.t('narr_r2_selina_legal'));
                } else if (d.decision1 === 'both') {
                    cashDelta -= 18000000; culturalDelta += 8; reputationDelta += 7; governanceDelta += 3;
                    narrativeParts.push(window.mySimulation.t('narr_r2_selina_both'));
                }

                if (d.decision2 === 'none') {
                    envDelta -= 15; cashDelta -= 25000000; reputationDelta -= 5;
                    narrativeParts.push(window.mySimulation.t('narr_r2_uaespnn_none'));
                } else if (d.decision2 === 'basic') {
                    envDelta += 6; cashDelta -= 12000000;
                    narrativeParts.push(window.mySimulation.t('narr_r2_uaespnn_basic'));
                } else if (d.decision2 === 'complete') {
                    envDelta += 15; cashDelta -= 85000000; reputationDelta += 4;
                    narrativeParts.push(window.mySimulation.t('narr_r2_uaespnn_complete'));
                }

                if (d.decision3 === 'pure') {
                    culturalDelta += 10; communityDelta -= 8; governanceDelta -= 4;
                    narrativeParts.push(window.mySimulation.t('narr_r2_exp_pure'));
                } else if (d.decision3 === 'balanced') {
                    culturalDelta += 5; communityDelta += 6; governanceDelta += 5;
                    narrativeParts.push(window.mySimulation.t('narr_r2_exp_balanced'));
                } else if (d.decision3 === 'modern') {
                    culturalDelta -= 10; communityDelta += 4; governanceDelta -= 2;
                    narrativeParts.push(window.mySimulation.t('narr_r2_exp_modern'));
                }

                if (d.decision4 === 'accept_asis') {
                    cashDelta += 8000000; culturalDelta -= 6; governanceDelta -= 8;
                    narrativeParts.push(window.mySimulation.t('narr_r2_redd_accept'));
                } else if (d.decision4 === 'renegotiate') {
                    culturalDelta += 4; governanceDelta += 6; envDelta += 3;
                    narrativeParts.push(window.mySimulation.t('narr_r2_redd_negotiate'));
                } else if (d.decision4 === 'reject') {
                    culturalDelta += 2; envDelta -= 2;
                    narrativeParts.push(window.mySimulation.t('narr_r2_redd_reject'));
                }
            }

            if (period === 3) {
                if (d.decision1 === 'silence') {
                    reputationDelta -= 12; communityDelta -= 3;
                    narrativeParts.push(window.mySimulation.t('narr_r3_comm_silence'));
                } else if (d.decision1 === 'reactive') {
                    reputationDelta -= 3;
                    narrativeParts.push(window.mySimulation.t('narr_r3_comm_reactive'));
                } else if (d.decision1 === 'proactive') {
                    reputationDelta += 8; communityDelta += 3;
                    narrativeParts.push(window.mySimulation.t('narr_r3_comm_proactive'));
                } else if (d.decision1 === 'offensive') {
                    reputationDelta -= 5; culturalDelta -= 2;
                    narrativeParts.push(window.mySimulation.t('narr_r3_comm_offensive'));
                }

                if (d.decision2 === 'minimal') {
                    cashDelta -= 8000000; reputationDelta -= 6; envDelta -= 4;
                    narrativeParts.push(window.mySimulation.t('narr_r3_safety_minimal'));
                } else if (d.decision2 === 'moderate') {
                    cashDelta -= 28000000; reputationDelta += 4; envDelta += 4;
                    narrativeParts.push(window.mySimulation.t('narr_r3_safety_moderate'));
                } else if (d.decision2 === 'complete') {
                    cashDelta -= 52000000; reputationDelta += 10; envDelta += 8; communityDelta += 3;
                    narrativeParts.push(window.mySimulation.t('narr_r3_safety_complete'));
                }

                if (d.decision3 === 'bank') {
                    cashDelta += 80000000; governanceDelta -= 2;
                    narrativeParts.push(window.mySimulation.t('narr_r3_fin_bank'));
                } else if (d.decision3 === 'coop') {
                    cashDelta += 60000000; reputationDelta += 4; culturalDelta += 2;
                    narrativeParts.push(window.mySimulation.t('narr_r3_fin_coop'));
                } else if (d.decision3 === 'redd') {
                    cashDelta += 150000000; culturalDelta -= 4; governanceDelta -= 3;
                    narrativeParts.push(window.mySimulation.t('narr_r3_fin_redd'));
                } else if (d.decision3 === 'members') {
                    cashDelta += 35000000; communityDelta -= 6; governanceDelta -= 4;
                    narrativeParts.push(window.mySimulation.t('narr_r3_fin_members'));
                }

                if (d.decision4 === 'formal') {
                    governanceDelta += 4;
                } else if (d.decision4 === 'hybrid') {
                    governanceDelta += 7; culturalDelta += 2;
                } else if (d.decision4 === 'consultive') {
                    governanceDelta += 10; culturalDelta += 3; communityDelta += 4;
                }
            }

            if (period === 4) {
                if (d.decision1 === 'reject') {
                    cashDelta -= 0; governanceDelta += 3;
                    narrativeParts.push(window.mySimulation.t('narr_r4_mincit_reject'));
                } else if (d.decision1 === 'conditional') {
                    cashDelta += 180000000; reputationDelta += 6; governanceDelta += 4;
                    narrativeParts.push(window.mySimulation.t('narr_r4_mincit_conditional'));
                } else if (d.decision1 === 'accept') {
                    cashDelta += 250000000; reputationDelta += 4; culturalDelta -= 3;
                    narrativeParts.push(window.mySimulation.t('narr_r4_mincit_accept'));
                }

                if (d.decision2 === 'traditional') {
                    culturalDelta += 6; communityDelta -= 10; governanceDelta -= 4;
                    narrativeParts.push(window.mySimulation.t('narr_r4_gov_traditional'));
                } else if (d.decision2 === 'dual') {
                    culturalDelta += 4; communityDelta += 2; governanceDelta += 6;
                    narrativeParts.push(window.mySimulation.t('narr_r4_gov_dual'));
                } else if (d.decision2 === 'integrated') {
                    culturalDelta += 2; communityDelta += 10; governanceDelta += 12;
                    narrativeParts.push(window.mySimulation.t('narr_r4_gov_integrated'));
                }

                if (d.decision3 === 'tourism_only') {
                    cashDelta += 20000000; envDelta -= 2;
                    narrativeParts.push(window.mySimulation.t('narr_r4_div_tourism'));
                } else if (d.decision3 === 'redd_tourism') {
                    cashDelta += 180000000; envDelta += 6; culturalDelta += 2;
                    narrativeParts.push(window.mySimulation.t('narr_r4_div_redd'));
                } else if (d.decision3 === 'full') {
                    cashDelta += 260000000; envDelta += 10; reputationDelta += 8; culturalDelta += 4;
                    narrativeParts.push(window.mySimulation.t('narr_r4_div_full'));
                }

                if (d.decision4 === 'basic') {
                    cashDelta += 15000000;
                } else if (d.decision4 === 'moderate') {
                    cashDelta -= 35000000; reputationDelta += 5; envDelta += 3;
                } else if (d.decision4 === 'aggressive') {
                    cashDelta -= 90000000; reputationDelta += 12; envDelta += 10; culturalDelta += 4;
                    narrativeParts.push(window.mySimulation.t('narr_r4_cert_aggressive'));
                }
            }

            ds.cash += cashDelta;
            ds.cultural = Math.max(0, Math.min(100, ds.cultural + culturalDelta));
            ds.governance = Math.max(0, Math.min(100, ds.governance + governanceDelta));
            ds.env = Math.max(0, Math.min(100, ds.env + envDelta));
            ds.reputation = Math.max(0, Math.min(100, ds.reputation + reputationDelta));
            ds.community = Math.max(0, Math.min(100, ds.community + communityDelta));

            ds.cashHistory.push(ds.cash);
            ds.culturalHistory.push(ds.cultural);
            ds.governanceHistory.push(ds.governance);
            ds.envHistory.push(ds.env);
            ds.reputationHistory.push(ds.reputation);
            ds.communityHistory.push(ds.community);

            var self = this;
            /* v1.1.0: removed racy setTimeout N+2 desync; panel refreshes on the real period:submitted / period:undone events wired in setupUI. */

            return {
                period: period,
                cashDelta: cashDelta,
                cash: ds.cash,
                cultural: ds.cultural,
                governance: ds.governance,
                env: ds.env,
                reputation: ds.reputation,
                community: ds.community,
                narrative: narrativeParts.join('<br>')
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => 'COP ' + Math.round(v).toLocaleString('es-CO'));
            uiManager.bind('culturalDisplay', 'domainState.cultural',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('governanceDisplay', 'domainState.governance',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('envDisplay', 'domainState.env',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('reputationDisplay', 'domainState.reputation',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('communityDisplay', 'domainState.community',
                (v) => Math.round(v) + ' / 100');

            uiManager.bind('culturalBar', 'domainState.cultural', function(v) {
                var el = document.getElementById('culturalBar');
                if (el) el.style.width = Math.round(v) + '%';
                return '';
            });
            uiManager.bind('governanceBar', 'domainState.governance', function(v) {
                var el = document.getElementById('governanceBar');
                if (el) el.style.width = Math.round(v) + '%';
                return '';
            });
            uiManager.bind('envBar', 'domainState.env', function(v) {
                var el = document.getElementById('envBar');
                if (el) el.style.width = Math.round(v) + '%';
                return '';
            });
            uiManager.bind('reputationBar', 'domainState.reputation', function(v) {
                var el = document.getElementById('reputationBar');
                if (el) el.style.width = Math.round(v) + '%';
                return '';
            });
            uiManager.bind('communityBar', 'domainState.community', function(v) {
                var el = document.getElementById('communityBar');
                if (el) el.style.width = Math.round(v) + '%';
                return '';
            });


            if (!this._wired) {
                var _self = this;
                var _refresh = function() { try { _self._updateBriefing(window.mySimulation.state); } catch (e) {} };
                var _sim = window.mySimulation;
                if (_sim && _sim.eventBus && typeof _sim.eventBus.on === 'function') {
                    _sim.eventBus.on('period:submitted', _refresh);
                    _sim.eventBus.on('period:undone', _refresh);
                }
                document.addEventListener('express:langchanged', _refresh);
                this._wired = true;
            }
        }

