        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1].results || {};
            var cash = last.cash || 0;
            var cultural = last.cultural || 0;
            var governance = last.governance || 0;
            var env = last.env || 0;
            var reputation = last.reputation || 0;
            var community = last.community || 0;

            var compositeScore = (cultural + governance + env + reputation + community) / 5;
            var cashScore = Math.min(100, Math.max(0, (cash / 300000000) * 100));
            var finalScore = (compositeScore * 0.6) + (cashScore * 0.4);

            var performance = 'Aprendiz';
            if (finalScore > 45) performance = 'Competente';
            if (finalScore > 60) performance = 'Sólido';
            if (finalScore > 75) performance = 'Sobresaliente';
            if (finalScore > 87) performance = 'Ejemplar';

            var insights = [];
            if (cultural < 50) insights.push(window.mySimulation.t('insight_cultural_weak'));
            else if (cultural > 80) insights.push(window.mySimulation.t('insight_cultural_strong'));
            if (governance < 50) insights.push(window.mySimulation.t('insight_governance_weak'));
            else if (governance > 80) insights.push(window.mySimulation.t('insight_governance_strong'));
            if (env < 50) insights.push(window.mySimulation.t('insight_env_weak'));
            else if (env > 80) insights.push(window.mySimulation.t('insight_env_strong'));
            if (cash > 400000000) insights.push(window.mySimulation.t('insight_cash_strong'));
            else if (cash < 80000000) insights.push(window.mySimulation.t('insight_cash_weak'));
            if (insights.length === 0) insights.push(window.mySimulation.t('insight_balanced'));

            return {
                finalScore: Math.round(finalScore),
                cash: cash,
                cultural: cultural,
                governance: governance,
                env: env,
                reputation: reputation,
                community: community,
                performance: performance,
                insights: insights
            };
        }

